use super::*;
use crate::{Fr,G2Projective};
use ark_ff::{BigInt,PrimeField,Field,Zero};
fn ark(x:Fq)->ark_ref::Fq{ark_ref::Fq::from_bigint(BigInt(x.to_canonical())).unwrap()}
fn raw(values:[[u64;4];8])->Ifma8<FqConfig,true>{let columns:[[u64;8];5]=core::array::from_fn(|j|core::array::from_fn(|i|{let bit=j*52;let word=bit/64;let off=bit%64;let mut value=values[i][word]>>off;if off!=0&&word<3{value|=values[i][word+1]<<(64-off);}value&MASK}));unsafe{Ifma8(core::mem::transmute(columns),PhantomData)}}
fn bounds(v:&Ifma8<FqConfig,true>){let columns:[[u64;8];5]=unsafe{core::mem::transmute(v.0)};let p2=crate::portable::add4(FqConfig::P,FqConfig::P).0;for i in 0..8{assert!(columns[4][i]>>48==0);let mut words=[0u64;4];for j in 0..5{assert!(columns[j][i]<=MASK);let bit=j*52;let w=bit/64;let off=bit%64;words[w]|=columns[j][i]<<off;if off!=0&&w<3{words[w+1]|=columns[j][i]>>(64-off);}}assert!(crate::portable::less(words,p2));}}
#[test]fn raw_boundaries_chains_and_arkworks(){assert_eq!(FACTOR,[922702722367487,4251595470861686,233696365179491,24128175338]);assert_eq!(QUOTIENT,[2168209193523251,822091209083389,2454298932930039,2042266689554]);assert_eq!(-SHORT_GAMMA,BETA);let p=FqConfig::P;let p2=crate::portable::add4(p,p).0;let mut values=vec![[0;4],[1,0,0,0],p,p2,crate::portable::sub4(p,[1,0,0,0]).0,crate::portable::sub4(p2,[1,0,0,0]).0];for bit in 0..255{let mut w=[0u64;4];w[bit/64]=1<<(bit%64);if crate::portable::less(w,p2){values.push(w);values.push(crate::portable::sub4(w,[1,0,0,0]).0);}}let mut seed=0xf43ca76960b18325u64;for _ in 0..4096{let mut w=[0u64;4];for word in &mut w{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;*word=seed;}while !crate::portable::less(w,p2){w=crate::portable::sub4(w,p2).0;}values.push(w);}let hinv=ark_ref::Fq::from(2u64).pow([256]).inverse().unwrap();let factor=ark(BETA);let mut checked=0;for group in values.chunks(8){let input=core::array::from_fn(|i|group[i%group.len()]);let mut expected=input.map(|w|{let bytes=w.into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>();ark_ref::Fq::from_le_bytes_mod_order(&bytes)*hinv});let mut current=raw(input);for _ in 0..8{current=current.mul_phi_short();bounds(&current);let actual=current.get();for i in 0..8{expected[i]*=factor;assert_eq!(ark(actual[i]),expected[i]);if expected[i].is_zero(){assert_eq!(actual[i],Fq::ZERO);}checked+=1;}}}eprintln!("NEGATIVE_PHI_NATIVE_LANES {checked}");}
#[test]fn complete_transforms_tails_and_scalar_correction(){let lambda=Fr::from_decimal("4407920970296243842393367215006156084916469457145843978461");let base=G2Projective::batch_to_affine(&(0..64).map(|i|G2Affine::GENERATOR*Fr::from(i+1)).collect::<Vec<_>>());let mapped=base.iter().map(|p|(*p*lambda).to_affine()).collect::<Vec<_>>();let mapped2=base.iter().map(|p|(*p*lambda.square()).to_affine()).collect::<Vec<_>>();let mut outputs=0;for n in[0usize,1,2,3,4,5,7,8,9,31,63,64,65,511,2048,2049]{let original=(0..n).map(|i|if i%17==0{G2Affine::IDENTITY}else{base[i%64]}).collect::<Vec<_>>();let mut actual=original.clone();let ptr=actual.as_ptr();let cap=actual.capacity();for pass in 0..3{transform(&mut actual);for i in 0..n{let expected=if original[i].is_identity(){G2Affine::IDENTITY}else{match pass{0=>mapped[i%64],1=>mapped2[i%64],_=>original[i]}};assert_eq!(actual[i],expected);assert!(actual[i].is_on_curve());outputs+=1;}assert_eq!(actual.as_ptr(),ptr);assert_eq!(actual.capacity(),cap);}}eprintln!("NEGATIVE_PHI_POINT_OUTPUTS {outputs}");}
#[test]fn workers_with_small_stacks(){let base=G2Projective::batch_to_affine(&(0..16).map(|i|G2Affine::GENERATOR*Fr::from(i+777)).collect::<Vec<_>>());let mut count=0;for workers in[1,4,16,32]{let jobs=(0..workers).map(|id|{let original=base.clone();std::thread::Builder::new().name(format!("short-negative-phi-{id}")).stack_size(512*1024).spawn(move||{let mut points=original.clone();for _ in 0..3{transform(&mut points);}assert_eq!(points,original);}).unwrap()}).collect::<Vec<_>>();for job in jobs{job.join().unwrap();count+=1;}}eprintln!("NEGATIVE_PHI_SMALL_STACK_WORKERS {count}");}
